"use client";

/**
 * Device drop: a headline settles in on the left while a phone is set down on
 * the right with weight, a small overshoot and a soft contact shadow under it.
 *
 * Written by Better Design. Painted from the theme prop; with no screenshot the
 * phone shows a placeholder app drawn from the same tokens.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, PHONE_CASE, PhoneFrame, pickFont, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

/** Frame the phone starts to fall. */
const DROP_AT = 12;
/** Rendered width of the phone case, in pixels; the height follows the real case. */
const PHONE_W = 410;
const PHONE_H = (PHONE_W / PHONE_CASE.width) * PHONE_CASE.height;

export interface DeviceDropProps {
  headline?: string;
  subline?: string;
  /** Image URL or static file for the phone screen. Drawn as a placeholder app when absent. */
  screenshot?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

function PlaceholderApp({ theme }: { theme: VideoTheme }) {
  const line = (w: string, h: number, c = withAlpha(theme.foreground, 0.12)) => (
    <div style={{ width: w, height: h, borderRadius: h / 2, background: c }} />
  );
  return (
    <div style={{ position: "absolute", inset: 0, background: theme.background, display: "flex", flexDirection: "column", padding: "64px 26px 0" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 28 }}>
        {line("46%", 22, withAlpha(theme.foreground, 0.85))}
        <div style={{ width: 40, height: 40, borderRadius: 20, background: theme.muted, border: `1px solid ${theme.border}` }} />
      </div>
      <div
        style={{
          height: 190,
          borderRadius: 26,
          padding: 22,
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-end",
          gap: 12,
          background: `linear-gradient(140deg, oklch(1 0 0 / 0.22), oklch(1 0 0 / 0) 70%), ${theme.primary}`,
        }}
      >
        {line("62%", 16, withAlpha(theme.primaryForeground, 0.9))}
        {line("38%", 12, withAlpha(theme.primaryForeground, 0.6))}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 14, marginTop: 26 }}>
        {[0.7, 0.55, 0.64, 0.48].map((w, i) => (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: 16, padding: 16, borderRadius: 20, background: theme.card, border: `1px solid ${theme.border}` }}>
            <div style={{ width: 48, height: 48, borderRadius: 14, background: i === 0 ? withAlpha(theme.primary, 0.18) : theme.muted }} />
            <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 9 }}>
              {line(`${w * 100}%`, 13, withAlpha(theme.foreground, 0.7))}
              {line(`${w * 60}%`, 10)}
            </div>
          </div>
        ))}
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 88, display: "flex", justifyContent: "space-around", alignItems: "center", background: theme.card, borderTop: `1px solid ${theme.border}` }}>
        {[0, 1, 2, 3].map((i) => (
          <div key={i} style={{ width: 26, height: 26, borderRadius: 8, background: i === 0 ? theme.primary : withAlpha(theme.foreground, 0.16) }} />
        ))}
      </div>
    </div>
  );
}

/** A headline on the left and a phone set down on the right with weight. */
export function DeviceDrop({
  headline = "Everything you need, in your pocket.",
  subline = "Your product, on every screen you own.",
  screenshot,
  theme: themeOverride,
  font,
}: DeviceDropProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);

  // A low-damping spring carries the phone a little past rest, then settles.
  const drop = spring({ frame: frame - DROP_AT, fps, config: { damping: 13, stiffness: 120, mass: 1.1 } });
  const y = interpolate(drop, [0, 1], [-1100, 0]);
  const height = Math.max(0, -y) / 1100;
  const tilt = interpolate(drop, [0, 1], [-7, 0]);
  // A brief squash on contact sells the weight.
  const squash = 1 - Math.max(0, y) * 0.0012;

  const head = easings.out(interpolate(frame, [4, 28], [0, 1], clamp));
  const sub = easings.out(interpolate(frame, [14, 38], [0, 1], clamp));

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family }}>
      <div style={{ position: "absolute", left: 160, top: 0, bottom: 0, width: 820, display: "flex", flexDirection: "column", justifyContent: "center", gap: 36 }}>
        <div style={{ fontSize: 96, fontWeight: 700, lineHeight: 1.04, letterSpacing: "-0.035em", color: theme.foreground, opacity: head, transform: `translateY(${(1 - head) * 28}px)` }}>
          {headline}
        </div>
        <div style={{ fontSize: 38, fontWeight: 500, lineHeight: 1.35, color: theme.mutedForeground, opacity: sub, transform: `translateY(${(1 - sub) * 18}px)` }}>
          {subline}
        </div>
      </div>

      <div style={{ position: "absolute", left: 1370 - PHONE_W / 2, top: (1080 - PHONE_H) / 2 + 10, width: PHONE_W, height: PHONE_H }}>
        <div
          style={{
            position: "absolute",
            left: "6%",
            right: "6%",
            bottom: -26,
            height: 44,
            borderRadius: "50%",
            background: "oklch(0 0 0 / 0.38)",
            filter: "blur(18px)",
            opacity: (1 - height) * Math.min(1, drop * 2),
            transform: `scaleX(${0.55 + 0.45 * (1 - height)})`,
          }}
        />
        <div
          style={{
            position: "absolute",
            inset: 0,
            transformOrigin: "50% 100%",
            transform: `translateY(${y}px) rotate(${tilt}deg) scaleY(${squash})`,
          }}
        >
          <PhoneFrame width={PHONE_W}>
            {screenshot ? <Img src={srcOf(screenshot)} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <PlaceholderApp theme={theme} />}
          </PhoneFrame>
        </div>
      </div>
    </AbsoluteFill>
  );
}
